code_sketch:
val q = Channel<Order>(capacity = 10_000,
                       onBufferOverflow = BufferOverflow.DROP_OLDEST,
                       onUndeliveredElement = { it.close() })   // runs for each shed item
launch { for (o in q) process(o) }
val r = q.trySend(order)                  // non-suspending: full or closed, never waits
if (r.isFailure) dropped.increment()

